        [DllImport("libc", EntryPoint = "getgid")] static extern uint getgid_();
        [DllImport("libc", EntryPoint = "getegid")] static extern uint getegid_();
        [DllImport("libc", EntryPoint = "getppid")] static extern int getppid_();
        [DllImport("libc", EntryPoint = "umask")] static extern uint umask_(uint mask);
        [DllImport("libc", EntryPoint = "link", SetLastError = true)] static extern int link_(string oldpath, string newpath);
        [DllImport("libc", EntryPoint = "chown", SetLastError = true)] static extern int chown_(string path, int owner, int group);
        [DllImport("libc", EntryPoint = "lchown", SetLastError = true)] static extern int lchown_(string path, int owner, int group);
        [DllImport("libc", EntryPoint = "confstr", SetLastError = true)] static extern UIntPtr confstr_(int name, byte[]? buf, UIntPtr len);
        [DllImport("libc", EntryPoint = "mkfifo", SetLastError = true)] static extern int mkfifo_(string path, uint mode);
