    internal static partial class Builtins
    {
        /// <summary>d.copy() of a mapping that is not a dict (os.environ, a __dict__ view): a dict with the same items.</summary>
        public static OrderedDictionary<K, V> copy<K, V>(this IDictionary<K, V> d) where K : notnull
        {
            var r = new OrderedDictionary<K, V>();
            foreach (var kv in d) r[kv.Key] = kv.Value;
            return r;
        }
    }
