            public OrderedDictionary<string, string> copy() => new OrderedDictionary<string, string>(this);
            public string __repr__() => "environ({" + string.Join(", ", this.Select(kv => Builtins.repr(kv.Key) + ": " + Builtins.repr(kv.Value))) + "})";
            public override string ToString() => __repr__();
        }

        public static readonly IDictionary<string, string> environ = new _Environ();

        /// <summary>getenv(key, default=None): os.environ.get(key, default).</summary>
        public static string? getenv(string key, string? @default = null) => environ.TryGetValue(key, out var v) ? v : @default;
        /// <summary>putenv / unsetenv: change the process environment without changing os.environ (as in CPython).</summary>
        public static void putenv(string key, string value) => Environment.SetEnvironmentVariable(key, value);
        public static void unsetenv(string key) => Environment.SetEnvironmentVariable(key, null);
        /// <summary>The directories a program name is looked up in (PATH, else os.defpath).</summary>
        public static List<string> get_exec_path(IDictionary<string, string>? env = null)
        {
            var e = env ?? environ;
            string p = e.TryGetValue("PATH", out var v) ? v : defpath;
            return p.Split(pathsep[0]).ToList();
        }

