        }
        public static string strerror(long code) => OsErrors.StrError(code);

        static long Posix(string what, Func<long> f) => Win ? throw new MissingMemberException($"module 'os' has no attribute '{what}'") : f();

        /// <summary>confstr(name): a configuration string ('CS_PATH', 'CS_GNU_LIBC_VERSION', ...) on Linux.</summary>
        public static readonly OrderedDictionary<string, long> confstr_names = new OrderedDictionary<string, long>
        {
            ["CS_PATH"] = 0, ["CS_GNU_LIBC_VERSION"] = 2, ["CS_GNU_LIBPTHREAD_VERSION"] = 3,
        };
        public static string? confstr(object name)
        {
            long code = name is string s ? (confstr_names.TryGetValue(s, out var c) ? c : throw new ArgumentException("unrecognized configuration name")) : Convert.ToInt64(name);
            return OsNative.Confstr((int)code);
