        /// <summary>uname(): sysname, nodename, release, version, machine (posix).</summary>
        public static uname_result uname() => new uname_result(
            OperatingSystem.IsLinux() ? "Linux" : Mac ? "Darwin" : OperatingSystem.IsWindows() ? "Windows" : OperatingSystem.IsFreeBSD() ? "FreeBSD" : "Unknown",
            Environment.MachineName, Environment.OSVersion.Version.ToString(), System.Runtime.InteropServices.RuntimeInformation.OSDescription,
            System.Runtime.InteropServices.RuntimeInformation.OSArchitecture switch
            {
                System.Runtime.InteropServices.Architecture.X64 => "x86_64", System.Runtime.InteropServices.Architecture.Arm64 => Mac ? "arm64" : "aarch64",
                System.Runtime.InteropServices.Architecture.X86 => "i686", var a => a.ToString().ToLowerInvariant(),
            });

