            protected override string TypeName => "posix.uname_result";
            protected override string[] Fields => new[] { "sysname", "nodename", "release", "version", "machine" };
            protected override object?[] Values => new object?[] { sysname, nodename, release, version, machine };
            public string this[long i] => (string)Item(i)!;
        }

        // ── the terminal ──

        /// <summary>get_terminal_size(fd=1): the size of the terminal on that descriptor (OSError when it is not a terminal).</summary>
        public static TerminalSize get_terminal_size(long fd = 1)
        {
            bool redirected = fd == 0 ? Console.IsInputRedirected : fd == 2 ? Console.IsErrorRedirected : fd == 1 ? Console.IsOutputRedirected : true;
            if (!redirected)
            {
                try { return new TerminalSize(Console.WindowWidth, Console.WindowHeight); }
                catch (Exception e) when (e is IOException || e is PlatformNotSupportedException || e is InvalidOperationException) { }
            }
            throw Win ? new IOException("[WinError 6] The handle is invalid", 6) : OsErrors.Errno(25);
        }
        /// <summary>os.terminal_size((columns, lines)).</summary>
        public static TerminalSize terminal_size(System.Runtime.CompilerServices.ITuple size) => new TerminalSize(Convert.ToInt64(size[0]), Convert.ToInt64(size[1]));
        public static TerminalSize terminal_size(IList<long> size) => new TerminalSize(size[0], size[1]);

        // ── files and directories ──

        public static string getcwd() => Environment.CurrentDirectory;
        public static PyBytes getcwdb() => new PyBytes(Encoding.UTF8.GetBytes(Environment.CurrentDirectory));
        public static void chdir(string path)
        {
            if (!Directory.Exists(path)) throw File.Exists(path) ? OsErrors.NotADirectory(path) : OsErrors.NotFound(path);
            Environment.CurrentDirectory = path;
        }

        public static List<string> listdir(string path = ".")
        {
            if (!Directory.Exists(path)) throw File.Exists(path) ? OsErrors.NotADirectory(path) : OsErrors.PathNotFound(path);
            try { return Directory.EnumerateFileSystemEntries(path).Select(System.IO.Path.GetFileName).Select(x => x!).ToList(); }
            catch (Exception e) when (e is IOException || e is UnauthorizedAccessException) { throw OsErrors.From(e, path); }
        }

        public static void mkdir(string path, long mode = 0x1ff, object? dir_fd = null)
        {
            if (LExists(path)) throw OsErrors.Exists(path);
            string? parent = System.IO.Path.GetDirectoryName(System.IO.Path.GetFullPath(path));
            if (parent != null && !Directory.Exists(parent)) throw OsErrors.PathNotFound(path);
            try
            {
                if (Win) Directory.CreateDirectory(path);
                else Directory.CreateDirectory(path, (UnixFileMode)(mode & 0xfff));
            }
            catch (Exception e) when (e is IOException || e is UnauthorizedAccessException) { throw OsErrors.From(e, path); }
        }

        public static void makedirs(string name, long mode = 0x1ff, bool exist_ok = false)
        {
            if (Directory.Exists(name)) { if (!exist_ok) throw OsErrors.Exists(name); return; }
            if (LExists(name)) throw OsErrors.Exists(name);
            try
            {
                if (Win) Directory.CreateDirectory(name);
                else Directory.CreateDirectory(name, (UnixFileMode)(mode & 0xfff));
            }
            catch (Exception e) when (e is IOException || e is UnauthorizedAccessException) { throw OsErrors.From(e, name); }
        }

        public static void rmdir(string path, object? dir_fd = null)
        {
            if (!Directory.Exists(path)) throw File.Exists(path) ? OsErrors.NotADirectory(path) : OsErrors.NotFound(path);
            if (Directory.EnumerateFileSystemEntries(path).Any()) throw OsErrors.NotEmpty(path);
            try { Directory.Delete(path); }
            catch (Exception e) when (e is IOException || e is UnauthorizedAccessException) { throw OsErrors.From(e, path); }
        }

        /// <summary>removedirs(name): removes the directory, then each empty parent.</summary>
        public static void removedirs(string name)
        {
            rmdir(name);
            var (head, tail) = path.split(name);
            if (tail.Length == 0) (head, tail) = path.split(head);
            while (head.Length > 0 && tail.Length > 0)
            {
                try { rmdir(head); } catch (Exception e) when (e is IOException || e is UnauthorizedAccessException) { break; }
                (head, tail) = path.split(head);
            }
        }

        public static void remove(string path, object? dir_fd = null)
        {
            bool link = IsLink(path);
            if (!link && Directory.Exists(path)) throw OsErrors.IsADirectory(path);
            if (!link && !File.Exists(path)) throw OsErrors.NotFound(path);
            try { if (link && Directory.Exists(path) && Win) Directory.Delete(path); else File.Delete(path); }
            catch (Exception e) when (e is IOException || e is UnauthorizedAccessException) { throw OsErrors.From(e, path); }
        }
        public static void unlink(string path, object? dir_fd = null) => remove(path);

        /// <summary>rename(src, dst): on POSIX an existing file dst is replaced; on Windows that is FileExistsError.</summary>
        public static void rename(string src, string dst) => Move(src, dst, replace: !Win);
        /// <summary>replace(src, dst): rename that replaces an existing file dst on every platform.</summary>
        public static void replace(string src, string dst) => Move(src, dst, replace: true);
        public static void renames(string old, string @new)
        {
            var (head, _) = path.split(@new);
            if (head.Length > 0 && !path.exists(head)) makedirs(head);
            rename(old, @new);
        }

        static void Move(string src, string dst, bool replace)
        {
            if (!LExists(src)) throw OsErrors.NotFound(src, dst);
            try
            {
                if (Directory.Exists(src) && !IsLink(src))
                {
                    if (Directory.Exists(dst) && replace && !Directory.EnumerateFileSystemEntries(dst).Any()) Directory.Delete(dst);
                    else if (LExists(dst)) throw Directory.Exists(dst) ? OsErrors.NotEmpty(dst) : OsErrors.NotADirectory(src);
                    Directory.Move(src, dst);
                }
                else
                {
                    if (Directory.Exists(dst)) throw OsErrors.IsADirectory(dst);
                    if (!replace && LExists(dst)) throw OsErrors.Exists(src, dst);
                    File.Move(src, dst, overwrite: true);
                }
            }
            catch (Exception e) when (e is IOException && e.Message.Length > 0 && !e.Message.StartsWith("[") || e is UnauthorizedAccessException && !e.Message.StartsWith("["))
            {
                throw OsErrors.From(e, src, dst);
            }
        }

        /// <summary>chmod(path, mode): the permission bits on POSIX; on Windows only the read-only flag (mode without 0o200).</summary>
        public static void chmod(string path, long mode, object? dir_fd = null, bool follow_symlinks = true)
        {
            if (!LExists(path)) throw OsErrors.NotFound(path);
            try
            {
                if (Win)
                {
                    var attrs = File.GetAttributes(path);
                    File.SetAttributes(path, (mode & 0x80) != 0 ? attrs & ~FileAttributes.ReadOnly : attrs | FileAttributes.ReadOnly);
                }
                else File.SetUnixFileMode(path, (UnixFileMode)(mode & 0xfff));
            }
            catch (Exception e) when (e is IOException || e is UnauthorizedAccessException) { throw OsErrors.From(e, path); }
        }
        public static void lchmod(string path, long mode) => chmod(path, mode, follow_symlinks: false);

        /// <summary>chown(path, uid, gid): changes the owner (POSIX; -1 leaves one unchanged).</summary>
        public static void chown(string path, long uid, long gid, object? dir_fd = null, bool follow_symlinks = true)
        {
            if (Win) throw new MissingMemberException("module 'os' has no attribute 'chown'");
            int err = OsNative.Chown(path, uid, gid, follow_symlinks);
            if (err > 0) throw OsErrors.Errno(err, path);
            if (err < 0) throw new IOException("[Errno 38] Function not implemented: " + Builtins.repr(path), 38);
        }
        public static void lchown(string path, long uid, long gid) => chown(path, uid, gid, follow_symlinks: false);

        /// <summary>chflags / lchflags: BSD file flags, which neither Linux nor Windows has (AttributeError, as CPython there).</summary>
        public static void chflags(string path, long flags, bool follow_symlinks = true) => throw new MissingMemberException("module 'os' has no attribute 'chflags'");
        public static void lchflags(string path, long flags) => throw new MissingMemberException("module 'os' has no attribute 'lchflags'");

        /// <summary>makedev / major / minor: device numbers (glibc's encoding).</summary>
        public static long makedev(long major, long minor) => OsNative.MakeDev((uint)major, (uint)minor);
        public static long major(long device) => (long)((((ulong)device >> 32) & 0xfffff000) | (((ulong)device >> 8) & 0xfff));
        public static long minor(long device) => (long)((((ulong)device >> 12) & 0xffffff00) | ((ulong)device & 0xff));

        /// <summary>mkfifo(path, mode=0o666) / mknod(path, mode=0o600, device=0): named pipes and device files (POSIX).</summary>
        public static void mkfifo(string path, long mode = 0x1b6, object? dir_fd = null)
        {
            if (Win) throw new MissingMemberException("module 'os' has no attribute 'mkfifo'");
            int err = OsNative.Mkfifo(path, mode);
            if (err != 0) throw err > 0 ? OsErrors.Errno(err, path) : new IOException("[Errno 38] Function not implemented", 38);
        }
        public static void mknod(string path, long mode = 0x180, long device = 0, object? dir_fd = null)
        {
            if (Win) throw new MissingMemberException("module 'os' has no attribute 'mknod'");
            int err = OsNative.Mknod(path, mode, device);
            if (err != 0) throw err > 0 ? OsErrors.Errno(err, path) : new IOException("[Errno 38] Function not implemented", 38);
        }

        /// <summary>access(path, mode): can the file be found (F_OK), read (R_OK), written (W_OK), executed (X_OK)?</summary>
        public static bool access(string path, long mode, object? dir_fd = null, bool effective_ids = false, bool follow_symlinks = true)
        {
            if (!File.Exists(path) && !Directory.Exists(path)) return false;
            if (mode == F_OK) return true;
            try
            {
                if (Win)
                {
                    if ((mode & W_OK) != 0 && (File.GetAttributes(path) & FileAttributes.ReadOnly) != 0 && !Directory.Exists(path)) return false;
                    return true;
                }
                var m = File.GetUnixFileMode(path);
                if ((mode & R_OK) != 0 && (m & (UnixFileMode.UserRead | UnixFileMode.GroupRead | UnixFileMode.OtherRead)) == 0) return false;
                if ((mode & W_OK) != 0 && (m & (UnixFileMode.UserWrite | UnixFileMode.GroupWrite | UnixFileMode.OtherWrite)) == 0) return false;
                if ((mode & X_OK) != 0 && (m & (UnixFileMode.UserExecute | UnixFileMode.GroupExecute | UnixFileMode.OtherExecute)) == 0) return false;
                return true;
            }
            catch (Exception) { return false; }
        }

        /// <summary>readlink(path): the target a symbolic link points to.</summary>
        public static string readlink(string path, object? dir_fd = null)
        {
            if (!LExists(path)) throw OsErrors.NotFound(path);
            var target = new FileInfo(path).LinkTarget;
            if (target == null) throw OsErrors.NotALink(path);
            return target;
        }

        /// <summary>symlink(src, dst): makes dst a symbolic link to src (target_is_directory matters on Windows).</summary>
        public static void symlink(string src, string dst, bool target_is_directory = false, object? dir_fd = null)
        {
            if (LExists(dst)) throw OsErrors.Exists(src, dst);
            try
            {
                if (Win && (target_is_directory || Directory.Exists(System.IO.Path.Combine(System.IO.Path.GetDirectoryName(System.IO.Path.GetFullPath(dst)) ?? "", src))))
                    Directory.CreateSymbolicLink(dst, src);
                else File.CreateSymbolicLink(dst, src);
            }
            catch (Exception e) when (e is IOException || e is UnauthorizedAccessException) { throw OsErrors.From(e, src, dst); }
        }

        /// <summary>link(src, dst): makes dst a hard link to the file src.</summary>
        public static void link(string src, string dst, object? src_dir_fd = null, object? dst_dir_fd = null, bool follow_symlinks = true)
        {
            if (!LExists(src)) throw OsErrors.NotFound(src, dst);
            if (LExists(dst)) throw OsErrors.Exists(src, dst);
            int err = Win ? OsNative.WinHardLink(src, dst) : OsNative.Link(src, dst);
            if (err == 0) return;
            if (err < 0) throw new IOException("[Errno 38] Function not implemented", 38);
            throw Win ? new IOException($"[WinError {err}] {new System.ComponentModel.Win32Exception(err).Message}: {Builtins.repr(src)} -> {Builtins.repr(dst)}", err) : OsErrors.Errno(err, src, dst);
        }

        /// <summary>utime(path, times=None, *, ns=None): sets the access and modification times (now, (atime, mtime) seconds, or nanoseconds).</summary>
        public static void utime(string path, object? times = null, object? ns = null, object? dir_fd = null, bool follow_symlinks = true)
        {
            if (!LExists(path)) throw OsErrors.NotFound(path);
            DateTime at, mt;
            if (times != null && ns != null) throw new ArgumentException("utime: you may specify either 'times' or 'ns' but not both");
            if (times is System.Runtime.CompilerServices.ITuple t && t.Length == 2) { at = FromSeconds(Convert.ToDouble(t[0])); mt = FromSeconds(Convert.ToDouble(t[1])); }
            else if (ns is System.Runtime.CompilerServices.ITuple n && n.Length == 2) { at = FromNs(Convert.ToInt64(n[0])); mt = FromNs(Convert.ToInt64(n[1])); }
            else if (times == null && ns == null) at = mt = DateTime.UtcNow;
            else throw new InvalidCastException("utime: 'times' must be either a tuple of two ints or None");
            try
            {
                if (Directory.Exists(path)) { Directory.SetLastAccessTimeUtc(path, at); Directory.SetLastWriteTimeUtc(path, mt); }
                else { File.SetLastAccessTimeUtc(path, at); File.SetLastWriteTimeUtc(path, mt); }
            }
            catch (Exception e) when (e is IOException || e is UnauthorizedAccessException) { throw OsErrors.From(e, path); }
        }
        static readonly DateTime Epoch = new DateTime(1970, 1, 1, 0, 0, 0, DateTimeKind.Utc);
        static DateTime FromSeconds(double s) => Epoch.AddTicks((long)Math.Round(s * TimeSpan.TicksPerSecond));
        static DateTime FromNs(long ns) => Epoch.AddTicks(ns / 100);
        static long ToNs(DateTime utc) => (utc.ToUniversalTime() - Epoch).Ticks * 100;

        // ── helpers ──

        internal static bool IsLink(string p)
        {
            try { return new FileInfo(p).LinkTarget != null; }
            catch (Exception) { return false; }
        }
        /// <summary>Does the path name an entry (a broken symbolic link too)?</summary>
        internal static bool LExists(string p) => File.Exists(p) || Directory.Exists(p) || IsLink(p);

        // ── stat ──

        /// <summary>
        /// os.stat_result: st_mode, st_ino, st_dev, st_nlink, st_uid, st_gid, st_size and the times (float seconds and _ns
        /// integers); index access gives the ten integers of the tuple (times as whole seconds), as in CPython.
        /// </summary>
        internal sealed class stat_result : PyStructSeq
        {
            public readonly long st_mode, st_ino, st_dev, st_nlink, st_uid, st_gid, st_size;
            public readonly long st_atime_ns, st_mtime_ns, st_ctime_ns;
            public readonly long st_blksize, st_blocks, st_rdev;
            public readonly long st_file_attributes, st_reparse_tag;
            readonly long _birthNs;
            /// <summary>Identifies the file when the platform gave no inode / device (samestat compares it then).</summary>
            internal readonly string? __identity;

            public stat_result(long mode, long ino, long dev, long nlink, long uid, long gid, long size, long atime_ns, long mtime_ns, long ctime_ns,
                               long blksize = 0, long blocks = 0, long rdev = 0, long birthtime_ns = 0, long file_attributes = 0, long reparse_tag = 0, string? identity = null)
            {
                st_mode = mode; st_ino = ino; st_dev = dev; st_nlink = nlink; st_uid = uid; st_gid = gid; st_size = size;
                st_atime_ns = atime_ns; st_mtime_ns = mtime_ns; st_ctime_ns = ctime_ns;
                st_blksize = blksize; st_blocks = blocks; st_rdev = rdev; _birthNs = birthtime_ns;
                st_file_attributes = file_attributes; st_reparse_tag = reparse_tag; __identity = identity;
            }
            /// <summary>stat_result(sequence): from the ten integers.</summary>
            public stat_result(IList<long> seq) : this(seq[0], seq[1], seq[2], seq[3], seq[4], seq[5], seq[6], seq[7] * 1000000000, seq[8] * 1000000000, seq[9] * 1000000000) { }

            static double Seconds(long ns) => Math.Floor(ns / 1e9) + (ns - (long)Math.Floor(ns / 1e9) * 1000000000) * 1e-9;
            static long WholeSeconds(long ns) => (long)Math.Floor(ns / 1e9);
            public double st_atime => Seconds(st_atime_ns);
            public double st_mtime => Seconds(st_mtime_ns);
            public double st_ctime => Seconds(st_ctime_ns);
            public double st_birthtime => Seconds(_birthNs);
            public long st_birthtime_ns => _birthNs;

            protected override string TypeName => "os.stat_result";
            protected override string[] Fields => new[] { "st_mode", "st_ino", "st_dev", "st_nlink", "st_uid", "st_gid", "st_size", "st_atime", "st_mtime", "st_ctime" };
            protected override object?[] Values => new object?[] { st_mode, st_ino, st_dev, st_nlink, st_uid, st_gid, st_size, WholeSeconds(st_atime_ns), WholeSeconds(st_mtime_ns), WholeSeconds(st_ctime_ns) };
            public long this[long i] => (long)Item(i)!;
        }

        /// <summary>stat(path, *, follow_symlinks=True): the file's status (a path, or an open file descriptor).</summary>
        public static stat_result stat(object path, object? dir_fd = null, bool follow_symlinks = true) =>
            path is long fd ? fstat(fd) : StatPath(__path(path), follow_symlinks);
        public static stat_result stat(string path, object? dir_fd = null, bool follow_symlinks = true) => StatPath(path, follow_symlinks);
        /// <summary>lstat(path): stat without following a symbolic link.</summary>
        public static stat_result lstat(string path, object? dir_fd = null) => StatPath(path, false);
        public static stat_result lstat(object path, object? dir_fd = null) => StatPath(__path(path), false);

        /// <summary>fstat(fd): the status of an open file descriptor.</summary>
        public static stat_result fstat(long fd)
        {
            var e = Fd(fd);
            if (OperatingSystem.IsLinux())
            {
                int osfd = fd <= 2 && e.Path == null ? (int)fd : e.Stream is FileStream fs ? (int)fs.SafeFileHandle.DangerousGetHandle() : -1;
                if (osfd >= 0 && OsNative.Stat(osfd, "", true, out var st) == 0) return FromStatx(st);
            }
            if (e.Stream is FileStream wfs && OsNative.WinFileInfo(wfs.SafeFileHandle, out var wi) && e.Path != null) return FromWindows(e.Path, wi, true);
            if (e.Path != null) return StatPath(e.Path, true);
            // a console stream: a character device
            return new stat_result(0x2000 | 0x1b6, 0, 0, 1, 0, 0, 0, 0, 0, 0);
        }

        static stat_result StatPath(string p, bool follow)
        {
            if (p.Length == 0) throw OsErrors.NotFound(p);
            if (OperatingSystem.IsLinux())
            {
                int err = OsNative.Stat(OsNative.AT_FDCWD, p, follow, out var st);
                if (err == 0) return FromStatx(st);
                if (err > 0) throw OsErrors.Errno(err, p);
            }
            bool link = IsLink(p);
            bool exists = follow ? File.Exists(p) || Directory.Exists(p) : File.Exists(p) || Directory.Exists(p) || link;
            if (!exists) throw OsErrors.NotFound(p);
            if (Win && OsNative.WinFileInfo(p, follow, out var wi)) return FromWindows(p, wi, follow);
            return FromInfo(p, follow, link);
        }

        static stat_result FromStatx(OsNative.Statx st) => new stat_result(
            st.mode, (long)st.ino, OsNative.MakeDev(st.dev_major, st.dev_minor), st.nlink, st.uid, st.gid, (long)st.size,
            st.atime.tv_sec * 1000000000 + st.atime.tv_nsec, st.mtime.tv_sec * 1000000000 + st.mtime.tv_nsec, st.ctime.tv_sec * 1000000000 + st.ctime.tv_nsec,
            st.blksize, (long)st.blocks, OsNative.MakeDev(st.rdev_major, st.rdev_minor), (st.mask & 0x800) != 0 ? st.btime.tv_sec * 1000000000 + st.btime.tv_nsec : 0);

        /// <summary>CPython's st_mode on Windows: directory or regular file, read-only → 0o444 else 0o666, executables 0o111.</summary>
        static long WinMode(string p, FileAttributes attrs, bool linkNotFollowed)
        {
            long m;
            if (linkNotFollowed) m = 0xa000;
            else if ((attrs & FileAttributes.Directory) != 0) m = 0x4000 | 0x49;
            else m = 0x8000;
            m |= (attrs & FileAttributes.ReadOnly) != 0 ? 0x124 : 0x1b6;
            if (!linkNotFollowed && (attrs & FileAttributes.Directory) == 0)
            {
                string ext = System.IO.Path.GetExtension(p).ToLowerInvariant();
                if (ext is ".exe" or ".bat" or ".cmd" or ".com") m |= 0x49;
            }
            return m;
        }

        static stat_result FromWindows(string p, OsNative.ByHandleFileInformation wi, bool follow)
        {
            FileSystemInfo fi = Directory.Exists(p) ? new DirectoryInfo(p) : new FileInfo(p);
            bool link = !follow && fi.LinkTarget != null;
            var attrs = (FileAttributes)wi.FileAttributes;
            long FileTime(uint low, uint high) { long ft = ((long)high << 32) | low; return (ft - 116444736000000000L) * 100; }
            long size = (attrs & FileAttributes.Directory) != 0 ? 0 : ((long)wi.FileSizeHigh << 32) | wi.FileSizeLow;
            return new stat_result(WinMode(p, attrs, link), (long)(((ulong)wi.FileIndexHigh << 32) | wi.FileIndexLow), wi.VolumeSerialNumber, wi.NumberOfLinks, 0, 0, size,
                FileTime(wi.AccessLow, wi.AccessHigh), FileTime(wi.WriteLow, wi.WriteHigh), FileTime(wi.WriteLow, wi.WriteHigh),
                birthtime_ns: FileTime(wi.CreationLow, wi.CreationHigh), file_attributes: wi.FileAttributes, reparse_tag: link ? 0xA000000C : 0);
        }

        /// <summary>stat from .NET's file information alone (no inode, device, links or owner): macOS, WebAssembly, or when the native call fails.</summary>
        static stat_result FromInfo(string p, bool follow, bool link)
        {
            FileSystemInfo fi = Directory.Exists(p) && !(link && !follow) ? new DirectoryInfo(p) : new FileInfo(p);
            if (follow && link) { try { fi = fi.ResolveLinkTarget(true) ?? fi; } catch (IOException) { } }
            bool dir = fi is DirectoryInfo;
            bool linkNotFollowed = link && !follow;
            long mode;
            if (Win) mode = WinMode(p, fi.Attributes, linkNotFollowed);
            else
            {
                long perm = 0x1a4;
                try { perm = (long)fi.UnixFileMode; } catch (Exception) { }
                mode = (linkNotFollowed ? 0xa000 : dir ? 0x4000 : 0x8000) | perm;
            }
            long size = linkNotFollowed ? Encoding.UTF8.GetByteCount(fi.LinkTarget ?? "") : fi is FileInfo f && !dir ? f.Length : dir && !Win ? 4096 : 0;
            string identity;
            try { identity = System.IO.Path.GetFullPath(linkNotFollowed ? p : fi.FullName); } catch (Exception) { identity = p; }
            if (Win) identity = identity.ToLowerInvariant();
            return new stat_result(mode, 0, 0, 1, 0, 0, size, ToNs(fi.LastAccessTimeUtc), ToNs(fi.LastWriteTimeUtc), ToNs(Win ? fi.LastWriteTimeUtc : fi.LastWriteTimeUtc),
                birthtime_ns: ToNs(fi.CreationTimeUtc), file_attributes: Win ? (long)fi.Attributes : 0, identity: identity);
        }

        // ── file descriptors ──

        internal sealed class FdEntry
        {
            public Stream Stream = null!;
            public string? Path;
            public bool Append;
        }

        static readonly Dictionary<long, FdEntry> _fds = new Dictionary<long, FdEntry>();
        static readonly ConditionalWeakTable<Stream, object> _fdOf = new ConditionalWeakTable<Stream, object>();

        static FdEntry Fd(long fd)
        {
            lock (_fds)
            {
                if (_fds.TryGetValue(fd, out var e)) return e;
                if (fd >= 0 && fd <= 2)
                {
                    e = new FdEntry { Stream = fd == 0 ? Console.OpenStandardInput() : fd == 1 ? Console.OpenStandardOutput() : Console.OpenStandardError() };
                    _fds[fd] = e;
                    return e;
                }
            }
            throw OsErrors.BadFd();
        }

        static long Allocate(FdEntry e)
        {
            lock (_fds)
            {
                // descriptors whose file object closed the stream are free again
                foreach (var stale in _fds.Where(kv => kv.Key > 2 && !kv.Value.Stream.CanRead && !kv.Value.Stream.CanWrite && !kv.Value.Stream.CanSeek).Select(kv => kv.Key).ToList())
                    _fds.Remove(stale);
                long fd = 3;
                while (_fds.ContainsKey(fd)) fd++;
                _fds[fd] = e;
                _fdOf.AddOrUpdate(e.Stream, fd);
                return fd;
            }
        }

        /// <summary>The descriptor of a stream opened elsewhere (f.fileno() of an open() file): it is entered in the table once.</summary>
        internal static long __register(Stream s)
        {
            lock (_fds)
            {
                if (_fdOf.TryGetValue(s, out var fd) && _fds.TryGetValue((long)fd, out var e) && ReferenceEquals(e.Stream, s)) return (long)fd;
                return Allocate(new FdEntry { Stream = s, Path = s is FileStream fs ? fs.Name : null });
            }
        }

        /// <summary>The stream behind a descriptor (io.FileIO(fd), os.fdopen).</summary>
        internal static Stream __fdstream(long fd) => Fd(fd).Stream;

        /// <summary>open(path, flags, mode=0o777): a file descriptor (O_RDONLY/O_WRONLY/O_RDWR with O_CREAT, O_EXCL, O_TRUNC, O_APPEND, ...).</summary>
        public static long open(string path, long flags, long mode = 0x1ff, object? dir_fd = null)
        {
            long acc = flags & 3;
            var access = acc == O_WRONLY ? FileAccess.Write : acc == O_RDWR ? FileAccess.ReadWrite : FileAccess.Read;
            bool creat = (flags & O_CREAT) != 0, excl = (flags & O_EXCL) != 0 && creat, trunc = (flags & O_TRUNC) != 0, append = (flags & O_APPEND) != 0;
            var fm = creat ? (excl ? FileMode.CreateNew : trunc ? FileMode.Create : FileMode.OpenOrCreate) : trunc ? FileMode.Truncate : FileMode.Open;
            if (access == FileAccess.Read && fm != FileMode.Open && fm != FileMode.OpenOrCreate)
            {
                // .NET cannot create or truncate a file opened only for reading: create it first, then open it
                if (fm == FileMode.CreateNew) { using (Create(path, FileMode.CreateNew, FileAccess.Write, mode, false)) { } }
                fm = creat ? FileMode.OpenOrCreate : FileMode.Open;
            }
            var stream = Create(path, fm, access, mode, (flags & O_TEMPORARY) != 0 && O_TEMPORARY != 0);
            return Allocate(new FdEntry { Stream = stream, Path = path, Append = append });
        }

        static FileStream Create(string path, FileMode fm, FileAccess access, long mode, bool deleteOnClose)
        {
            try
            {
                var opts = new FileStreamOptions { Mode = fm, Access = access, Share = FileShare.ReadWrite, Options = deleteOnClose ? FileOptions.DeleteOnClose : FileOptions.None };
                if (!Win && fm != FileMode.Open && fm != FileMode.Truncate) opts.UnixCreateMode = (UnixFileMode)(mode & 0x1ff);
                return new FileStream(path, opts);
            }
            catch (Exception e) when (e is IOException || e is UnauthorizedAccessException)
            {
                throw OsErrors.FromOpen(e, path, fm == FileMode.CreateNew);
            }
        }

        /// <summary>read(fd, n): at most n bytes (fewer at the end of the file; b'' after it).</summary>
        public static PyBytes read(long fd, long n)
        {
            if (n < 0) throw new ArgumentException("negative count");
            var s = Fd(fd).Stream;
            try
            {
                if (!s.CanRead) throw OsErrors.BadFd();
                var buf = new byte[n];
                int got = s.Read(buf, 0, (int)n);
                return new PyBytes(got == n ? buf : buf.AsSpan(0, got).ToArray());
            }
            catch (ObjectDisposedException) { throw OsErrors.BadFd(); }
            catch (NotSupportedException) { throw OsErrors.BadFd(); }
        }

        /// <summary>write(fd, data): writes the bytes, returns how many.</summary>
        public static long write(long fd, object data)
        {
            var e = Fd(fd);
            var bytes = ByteOps.From(data);
            // the console: in order with print() (and to where it is redirected in-process)
            if ((fd == 1 || fd == 2) && e.Path == null) return (fd == 1 ? sys_.__stdout__ : sys_.__stderr__).buffer.write(new PyBytes(bytes));
            try
            {
                if (!e.Stream.CanWrite) throw OsErrors.BadFd();
                if (e.Append && e.Stream.CanSeek) e.Stream.Seek(0, SeekOrigin.End);
                e.Stream.Write(bytes);
                e.Stream.Flush();
                return bytes.Length;
            }
            catch (ObjectDisposedException) { throw OsErrors.BadFd(); }
            catch (NotSupportedException) { throw OsErrors.BadFd(); }
        }

        public static long lseek(long fd, long pos, long how)
        {
            var s = Fd(fd).Stream;
            try { return s.Seek(pos, StreamOps.Origin(how)); }
            catch (ObjectDisposedException) { throw OsErrors.BadFd(); }
            catch (NotSupportedException) { throw OsErrors.Errno(29); }
        }

        public static void close(long fd)
        {
            FdEntry? e;
            lock (_fds)
            {
                if (!_fds.TryGetValue(fd, out e))
                {
                    if (fd >= 0 && fd <= 2) return;
                    throw OsErrors.BadFd();
                }
                _fds.Remove(fd);
            }
            if (fd > 2) e.Stream.Dispose();
        }

        /// <summary>closerange(lo, hi): closes the descriptors lo &lt;= fd &lt; hi, ignoring errors.</summary>
        public static void closerange(long fd_low, long fd_high)
        {
            List<long> fds;
            lock (_fds) fds = _fds.Keys.Where(k => k >= fd_low && k < fd_high && k > 2).ToList();
            foreach (var fd in fds) try { close(fd); } catch (Exception) { }
        }

        public static void fsync(long fd)
        {
            var s = Fd(fd).Stream;
            try { if (s is FileStream fs) fs.Flush(true); else s.Flush(); }
            catch (ObjectDisposedException) { throw OsErrors.BadFd(); }
        }
        public static void fdatasync(long fd) => fsync(fd);
        public static void ftruncate(long fd, long length)
        {
            var s = Fd(fd).Stream;
            try { s.SetLength(length); }
            catch (ObjectDisposedException) { throw OsErrors.BadFd(); }
        }

        /// <summary>copy_file_range(src, dst, count, offset_src=None, offset_dst=None): copies up to count bytes between descriptors.</summary>
        public static long copy_file_range(long src, long dst, long count, long? offset_src = null, long? offset_dst = null)
        {
            var input = Fd(src).Stream;
            var output = Fd(dst);
            if (offset_src is long os) input.Seek(os, SeekOrigin.Begin);
            if (offset_dst is long od) output.Stream.Seek(od, SeekOrigin.Begin);
            else if (output.Append && output.Stream.CanSeek) output.Stream.Seek(0, SeekOrigin.End);
            var buf = new byte[Math.Min(count, 1 << 20)];
            long done = 0;
            while (done < count)
            {
                int n = input.Read(buf, 0, (int)Math.Min(buf.Length, count - done));
                if (n <= 0) break;
                output.Stream.Write(buf, 0, n);
                done += n;
            }
            output.Stream.Flush();
            return done;
        }
        /// <summary>sendfile(out_fd, in_fd, offset, count): copies count bytes from offset of in_fd (None: its position) to out_fd.</summary>
        public static long sendfile(long out_fd, long in_fd, long? offset, long count) => copy_file_range(in_fd, out_fd, count, offset, null);
        /// <summary>set_blocking / get_blocking: descriptors here are always blocking.</summary>
        public static void set_blocking(long fd, bool blocking) => Fd(fd);
        public static bool get_blocking(long fd) { Fd(fd); return true; }

        /// <summary>isatty(fd): is the descriptor a terminal?</summary>
        public static bool isatty(long fd)
        {
            lock (_fds) if (_fds.TryGetValue(fd, out var e) && e.Path != null) return false;
            return fd == 0 ? !Console.IsInputRedirected : fd == 1 ? !Console.IsOutputRedirected : fd == 2 && !Console.IsErrorRedirected;
        }

        /// <summary>dup(fd): another descriptor for the same open file.</summary>
        public static long dup(long fd)
        {
            var e = Fd(fd);
            return Allocate(new FdEntry { Stream = e.Stream, Path = e.Path, Append = e.Append });
        }

        /// <summary>fdopen(fd, mode='r', ...): a file object over the descriptor (text, or binary for a mode with 'b').</summary>
        public static dynamic fdopen(long fd, string mode = "r", long buffering = -1, string? encoding = null, string? errors = null, string? newline = null, bool closefd = true)
        {
            var e = Fd(fd);
            return mode.Contains('b') ? new PyBinaryFile(e.Stream, fd.ToString(), mode, closefd) : new PyFile(e.Stream, fd.ToString(), mode, encoding, errors, newline, closefd);
        }

        // ── directory listings ──

        /// <summary>os.DirEntry: an entry of a scandir() listing (name, path, is_dir/is_file/is_symlink, stat()).</summary>
        internal sealed class DirEntry : IPyRepr
        {
            public readonly string name, path;
            stat_result? _stat, _lstat;
            public DirEntry(string dir, string name) { this.name = name; this.path = os_.path.join(dir, name); }
            public bool is_symlink() => IsLink(path);
            public bool is_dir(bool follow_symlinks = true) => follow_symlinks ? Directory.Exists(path) : Directory.Exists(path) && !is_symlink();
            public bool is_file(bool follow_symlinks = true) => follow_symlinks ? File.Exists(path) : File.Exists(path) && !is_symlink();
            public bool is_junction() => false;
            public stat_result stat(bool follow_symlinks = true) => follow_symlinks ? _stat ??= StatPath(path, true) : _lstat ??= StatPath(path, false);
            public long inode() => stat(false).st_ino;
            public string __fspath__() => path;
            public string __repr__() => $"<DirEntry {Builtins.repr(name)}>";
            public override string ToString() => __repr__();
            public static implicit operator string(DirEntry e) => e.path;
        }

        /// <summary>The iterator scandir() returns: DirEntry objects; a context manager (close()).</summary>
        internal sealed class ScandirIterator : IEnumerable<DirEntry>, IDisposable
        {
            readonly string _dir;
            readonly List<string> _names;
            public ScandirIterator(string dir, List<string> names) { _dir = dir; _names = names; }
            public IEnumerator<DirEntry> GetEnumerator() { foreach (var n in _names) yield return new DirEntry(_dir, n); }
            IEnumerator IEnumerable.GetEnumerator() => GetEnumerator();
            public void close() { }
            public void Dispose() { }
        }

        /// <summary>scandir(path='.'): the entries of a directory as DirEntry objects (in the directory's order).</summary>
        public static ScandirIterator scandir(string path = ".") => new ScandirIterator(path, listdir(path));
        public static BytesScandirIterator scandir(PyBytes path) => new BytesScandirIterator(path, scandir(fsdecode(path)));

        internal sealed class BytesScandirIterator : IEnumerable<BytesDirEntry>, IDisposable
        {
            readonly PyBytes _path;
            readonly ScandirIterator _entries;
            internal BytesScandirIterator(PyBytes path, ScandirIterator entries) { _path = path; _entries = entries; }
            public IEnumerator<BytesDirEntry> GetEnumerator()
            {
                foreach (var entry in _entries) yield return new BytesDirEntry(_path, entry);
            }
            IEnumerator IEnumerable.GetEnumerator() => GetEnumerator();
            public void close() => _entries.close();
            public void Dispose() => _entries.Dispose();
        }

        internal sealed class BytesDirEntry : IPyRepr
        {
            readonly DirEntry _entry;
            public readonly PyBytes name, path;
            internal BytesDirEntry(PyBytes root, DirEntry entry)
            {
                _entry = entry;
                name = fsencode(entry.name);
                path = os_.path.join(root, name);
            }
            public bool is_symlink() => _entry.is_symlink();
            public bool is_dir(bool follow_symlinks = true) => _entry.is_dir(follow_symlinks);
            public bool is_file(bool follow_symlinks = true) => _entry.is_file(follow_symlinks);
            public bool is_junction() => _entry.is_junction();
            public stat_result stat(bool follow_symlinks = true) => _entry.stat(follow_symlinks);
            public long inode() => _entry.inode();
            public PyBytes __fspath__() => path;
            public string __repr__() => $"<DirEntry {Builtins.repr(name)}>";
            public override string ToString() => __repr__();
        }

        /// <summary>
        /// walk(top, topdown=True, onerror=None, followlinks=False): (dirpath, dirnames, filenames) for each directory of the
        /// tree; top-down, removing names from dirnames prunes the walk.
        /// </summary>
        public static IEnumerable<(string, List<string>, List<string>)> walk(string top, bool topdown = true, Action<Exception>? onerror = null, bool followlinks = false)
        {
            var stack = new Stack<object>();
            stack.Push(top);
            while (stack.Count > 0)
            {
                var item = stack.Pop();
                if (item is ValueTuple<string, List<string>, List<string>> done) { yield return done; continue; }
                string dir = (string)item;
                List<string> names;
                try { names = listdir(dir); }
                catch (Exception e) when (e is IOException || e is UnauthorizedAccessException) { onerror?.Invoke(e); continue; }
                var dirs = new List<string>();
                var files = new List<string>();
                var walkInto = new List<string>();
                foreach (var n in names)
                {
                    string full = path.join(dir, n);
                    bool isDir = Directory.Exists(full);
                    (isDir ? dirs : files).Add(n);
                    if (isDir && !topdown && (followlinks || !IsLink(full))) walkInto.Add(full);
                }
                if (topdown)
                {
                    yield return (dir, dirs, files);
                    // (the caller may have changed dirs: walk what is left, in order)
                    for (int i = dirs.Count - 1; i >= 0; i--)
                    {
                        string full = path.join(dir, dirs[i]);
                        if (followlinks || !IsLink(full)) stack.Push(full);
                    }
                }
                else
                {
                    stack.Push((dir, dirs, files));
                    for (int i = walkInto.Count - 1; i >= 0; i--) stack.Push(walkInto[i]);
                }
            }
        }
    }
}
